-- 早期创建媒体以原准备记录与本人处置回执回收；用canvas_migration.py --apply精确核验旧结构。
ALTER TABLE canvas_resource_deletions MODIFY COLUMN idempotency_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin, MODIFY COLUMN request_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin, MODIFY COLUMN upload_id BIGINT UNSIGNED, ADD COLUMN creation_resource_id BIGINT UNSIGNED, ADD COLUMN disposal_receipt_id BIGINT UNSIGNED, ADD CONSTRAINT ck_canvas_deletion_origin CHECK ((upload_id IS NOT NULL AND idempotency_hash IS NOT NULL AND request_hash IS NOT NULL AND creation_resource_id IS NULL AND disposal_receipt_id IS NULL) OR (upload_id IS NULL AND idempotency_hash IS NULL AND request_hash IS NULL AND creation_resource_id IS NOT NULL AND disposal_receipt_id IS NOT NULL AND chunk_count = 0)), ADD CONSTRAINT fk_canvas_deletion_creation_resource FOREIGN KEY(creation_resource_id) REFERENCES canvas_creation_resources (id) ON DELETE RESTRICT ON UPDATE RESTRICT, ADD CONSTRAINT fk_canvas_deletion_disposal FOREIGN KEY(disposal_receipt_id) REFERENCES canvas_write_receipts (id) ON DELETE RESTRICT ON UPDATE RESTRICT, ADD CONSTRAINT uk_canvas_deletion_creation_resource UNIQUE (creation_resource_id), ADD INDEX idx_canvas_deletion_disposal (disposal_receipt_id);
